package dev.mineagent.runtime.core.config;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import dev.mineagent.runtime.api.config.ConfigPatch;import dev.mineagent.runtime.api.worker.WorkerEnvelope;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class AgentModelSettingsTest {
 @TempDir java.nio.file.Path root;
 @Test void defaultInheritanceIndependentOverridePersistenceAndRestore()throws Exception{UUID world=UUID.randomUUID(),a=UUID.randomUUID(),b=UUID.randomUUID();var file=root.resolve("config.db");try(var c=ServerConfigService.open(file)){c.apply(new ConfigPatch(c.snapshot().revision(),Map.of("provider.openai.baseUrl","https://api.deepseek.com/v1/")),true);assertEquals("DEFAULT",AgentModelSettings.read(c.snapshot().values(),world,a).mode());var selected=AgentModelSettings.save(c,world,b,0,"CUSTOM","deepseek-v4-pro","https://api.deepseek.com/v1");assertEquals(1,selected.revision());assertEquals("deepseek-flash",c.snapshot().values().get("provider.openai.model"));assertEquals("DEFAULT",AgentModelSettings.read(c.snapshot().values(),world,a).mode());c.apply(new ConfigPatch(c.snapshot().revision(),Map.of("provider.openai.model","future-default")),true);assertEquals("deepseek-v4-pro",AgentModelSettings.read(c.snapshot().values(),world,b).model());assertEquals("DEFAULT",AgentModelSettings.read(c.snapshot().values(),UUID.randomUUID(),b).mode());}
 try(var c=ServerConfigService.open(file)){assertEquals("deepseek-v4-pro",AgentModelSettings.read(c.snapshot().values(),world,b).model());assertThrows(IllegalStateException.class,()->AgentModelSettings.save(c,world,b,0,"DEFAULT","",""));AgentModelSettings.save(c,world,b,1,"DEFAULT","","");var request=AgentModelSettings.context(new WorkerEnvelope(1,UUID.randomUUID(),"model.stream",Map.of("prompt","hello")),world,b);assertFalse(AgentModelSettings.bind(c,request).payload().containsKey("agentModel"));assertEquals("future-default",c.snapshot().values().get("provider.openai.model"));}}
 @Test void customNamesValidateAndEndpointChangesCannotSilentlyRebind()throws Exception{var c=new ServerConfigService();UUID w=UUID.randomUUID(),a=UUID.randomUUID();c.apply(new ConfigPatch(0,Map.of("provider.openai.baseUrl","https://api.deepseek.com/v1/")),true);assertFalse(AgentModelSettings.validModel("x\n"));assertFalse(AgentModelSettings.validModel(""));AgentModelSettings.save(c,w,a,0,"CUSTOM","private/model-v2","https://api.deepseek.com/v1/");c.apply(new ConfigPatch(c.snapshot().revision(),Map.of("provider.openai.baseUrl","https://api.z.ai/api/paas/v4/")),true);assertThrows(IllegalStateException.class,()->AgentModelSettings.save(c,w,a,1,"CUSTOM","new","https://api.deepseek.com/v1/"));assertEquals("https://api.deepseek.com/v1/",AgentModelSettings.read(c.snapshot().values(),w,a).baseUrl());}
}
